package net.officefloor.hq.app.creditnote;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface CreditNoteRepository extends JpaRepository<CreditNote, Long> {

    /** An invoice's credit notes, oldest first. */
    List<CreditNote> findByInvoiceIdOrderByIdAsc(Long invoiceId);

    /** Total credited against an invoice (zero when nothing has been credited). */
    @Query("SELECT COALESCE(SUM(c.amount), 0) FROM CreditNote c WHERE c.invoiceId = :invoiceId")
    BigDecimal sumAmountByInvoiceId(Long invoiceId);
}
package net.officefloor.hq.app.creditnote;

import java.math.BigDecimal;
import java.time.Clock;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.invoice.Invoice;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class CreditNoteService {

    private final CreditNoteRepository creditNotes;
    private final InvoiceRepository invoices;
    private final Clock clock;
    private final Audit audit;

    public CreditNoteService(CreditNoteRepository creditNotes, InvoiceRepository invoices, Clock clock, Audit audit) {
        this.creditNotes = creditNotes;
        this.invoices = invoices;
        this.clock = clock;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<CreditNoteResponse> list(Long projectId, Long invoiceId) {
        find(projectId, invoiceId);
        return creditNotes.findByInvoiceIdOrderByIdAsc(invoiceId).stream().map(CreditNoteResponse::from).toList();
    }

    /**
     * Raises a credit note against an invoice that has been sent to the client and not cancelled. The
     * credit notes on an invoice may not add up to more than the invoice amount.
     */
    @Transactional
    public CreditNoteResponse issue(Long projectId, Long invoiceId, CreditNoteRequest request) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before raising a credit note");
        }
        if (invoice.getStatus() == InvoiceStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
        }
        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoiceId).add(request.amount());
        if (credited.compareTo(invoice.getAmount()) > 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Credit is more than the invoice amount");
        }
        CreditNote saved = creditNotes.saveAndFlush(new CreditNote(invoiceId, request.amount(), clock.instant()));
        audit.record("CREDIT_NOTE_ISSUED invoice=" + invoiceId + " amount=" + saved.getAmount().toPlainString());
        return CreditNoteResponse.from(saved);
    }

    private Invoice find(Long projectId, Long invoiceId) {
        return invoices.findById(invoiceId)
                .filter(i -> i.getProject().getId().equals(projectId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
    }
}
package net.officefloor.hq.app.payment;

import java.math.BigDecimal;
import java.util.Collection;
import java.util.List;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface PaymentRepository extends JpaRepository<Payment, Long> {

    /** An invoice's payments, oldest first. */
    List<Payment> findByInvoiceIdOrderByDateAscIdAsc(Long invoiceId);

    /** Total paid against an invoice (zero when nothing has been paid). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p WHERE p.invoiceId = :invoiceId")
    BigDecimal sumAmountByInvoiceId(Long invoiceId);

    /** Total paid against every invoice with any of the given statuses (zero when nothing has been paid). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p, Invoice i"
            + " WHERE p.invoiceId = i.id AND i.status IN :statuses")
    BigDecimal sumAmountByInvoiceStatusIn(Collection<InvoiceStatus> statuses);

    /** Total paid against invoices with any of the given statuses, per client; clients with none are left out. */
    @Query("SELECT pr.client.id AS clientId, SUM(p.amount) AS total FROM Payment p, Invoice i JOIN i.project pr"
            + " WHERE p.invoiceId = i.id AND i.status IN :statuses GROUP BY pr.client.id")
    List<InvoiceRepository.ClientTotal> sumAmountByInvoiceStatusInPerClient(Collection<InvoiceStatus> statuses);

    /** Total paid against each of the given invoices; invoices with no payments are left out. */
    @Query("SELECT p.invoiceId AS invoiceId, SUM(p.amount) AS paid FROM Payment p"
            + " WHERE p.invoiceId IN :invoiceIds GROUP BY p.invoiceId")
    List<InvoicePaidTotal> sumAmountByInvoiceIds(Collection<Long> invoiceIds);

    /** How much has been paid against one invoice. */
    interface InvoicePaidTotal {
        Long getInvoiceId();

        BigDecimal getPaid();
    }
}
import org.springframework.web.server.ResponseStatusException;

@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final ProjectRepository projects;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final SettingsService settings;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, ProjectRepository projects, PaymentRepository payments,
            ClientRepository clients, SettingsService settings, Audit audit) {
        this.invoices = invoices;
        this.projects = projects;
        this.clients = clients;
        this.payments = payments;
        this.settings = settings;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<InvoiceResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
        }
        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        return found.stream()
                .map(i -> InvoiceResponse.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
    }

    /**
     * A client's statement: every invoice across their projects with what is left to pay on each, and
     * the total they still owe, also grouped by job with a subtotal per job. Drafts are listed but not owed, as they have not been sent, nor are
     * void invoices, as they have been cancelled.
     */
    @Transactional(readOnly = true)
    public ClientStatementResponse statementForClient(Long clientId) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        List<ClientStatementResponse.Line> lines = found.stream()
                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines);
    }

    private Map<Long, BigDecimal> paidByInvoice(List<Invoice> found) {
        return found.isEmpty() ? Map.of()
                : payments.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
                        .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
                                PaymentRepository.InvoicePaidTotal::getPaid));
    }

    /**
     * One page of the invoices across all projects, with the name of the project each one is for,
     * narrowed to the given status when one is supplied. Pages are numbered from zero.
        }
        invoice.markSent();
        invoices.flush();
        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return toResponse(invoice);
    }

    /**
     * Cancels an invoice sent by mistake, so it no longer counts toward what is owed, and records the
     * cancellation in the audit log. Only a sent invoice with nothing yet paid against it can be voided.
     */
    @Transactional
    public InvoiceResponse cancel(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.SENT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "Only a sent invoice with no payments recorded can be cancelled");
        }
        invoice.markVoid();
        invoices.flush();
        audit.record("INVOICE_VOIDED id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return toResponse(invoice);
    }

    private InvoiceResponse toResponse(Invoice invoice) {
        return InvoiceResponse.from(invoice, payments.sumAmountByInvoiceId(invoice.getId()));
    }

package net.officefloor.hq.app.client;

import java.math.BigDecimal;
